import Foundation
import Security

enum KeychainError: Error {
    case duplicate
    case notFound
    case other(OSStatus)
}

func parseError(status: OSStatus) -> KeychainError? {
    switch status {
    case errSecSuccess:
        return nil
    case errSecDuplicateItem:
        return .duplicate
    case errSecItemNotFound:
        return .notFound
    default:
        return .other(status)
    }
}

let status: OSStatus = errSecDuplicateItem
if let err = parseError(status: status) {
    switch err {
    case .duplicate:
        print("Handled duplicate")
    default:
        print("Other error")
    }
}

