import Foundation
import Security

func makeGenericPasswordQuery(service: String, account: String, data: Data) -> [String: Any] {
    return [
        kSecClass as String: kSecClassGenericPassword,
        kSecAttrService as String: service,
        kSecAttrAccount as String: account,
        kSecValueData as String: data,
        kSecAttrAccessible as String: kSecAttrAccessibleWhenUnlocked
    ]
}

let testData = Data("tokenSecret".utf8)
let q = makeGenericPasswordQuery(service: "auth", account: "user1", data: testData)
let classValue = q[kSecClass as String] as? String
print("Has class: \(classValue == (kSecClassGenericPassword as String))")

